-- Explicit Data API access: compatible with the 2026-10-30 Supabase defaults.
-- Audited grants preserve application/RLS access on clean replay. No row changes.
-- Absent objects belong to pending releases; this migration does not deploy them.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public","shop_private" REVOKE ALL ON TABLES FROM PUBLIC,anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public","shop_private" REVOKE ALL ON SEQUENCES FROM PUBLIC,anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public","shop_private" REVOKE ALL ON FUNCTIONS FROM PUBLIC,anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

