DO $routines$
DECLARE item record; target text; role_name text;
BEGIN
  FOR item IN SELECT * FROM (VALUES
    ('public','save_shop_team_role','p_request_id uuid, p_shop_id uuid, p_role_key text, p_name text, p_name_ar text, p_permission_keys text[], p_archive boolean',ARRAY['authenticated','service_role']::text[]),
    ('shop_private','invite_shop_staff','p_request_id uuid, p_shop_id uuid, p_email text, p_display_name text, p_role_key text, p_location_ids uuid[], p_job_title text',ARRAY['service_role']::text[]),
    ('shop_private','require_charge_currency','p_currency text',ARRAY[]::text[]),
    ('shop_private','create_vendor','p_shop_id uuid, p_name text, p_contact_name text, p_phone text, p_email text, p_address text, p_tax_number text, p_notes text',ARRAY[]::text[]),
    ('public','create_vendor','p_shop_id uuid, p_name text, p_contact_name text, p_phone text, p_email text, p_address text, p_tax_number text, p_notes text',ARRAY['authenticated','service_role']::text[]),
    ('public','create_supplier_purchase','p_request_id uuid, p_shop_id uuid, p_vendor_id uuid, p_invoice_number text, p_issued_on date, p_notes text, p_items jsonb',ARRAY['authenticated','service_role']::text[]),
    ('shop_private','create_supplier_purchase','p_request_id uuid, p_shop_id uuid, p_vendor_id uuid, p_invoice_number text, p_issued_on date, p_notes text, p_items jsonb',ARRAY[]::text[]),
    ('public','prevent_posted_vendor_invoice_item_mutation','',ARRAY['service_role']::text[]),
    ('public','void_supplier_purchase','p_shop_id uuid, p_purchase_id uuid',ARRAY['authenticated','service_role']::text[]),
    ('shop_private','create_owner_shop','p_shop_name text, p_plan_slug text, p_business_mode business_mode',ARRAY[]::text[]),
    ('public','create_owner_shop','p_shop_name text, p_plan_slug text, p_business_mode business_mode',ARRAY['authenticated','service_role']::text[]),
    ('shop_private','void_supplier_purchase','p_shop_id uuid, p_purchase_id uuid',ARRAY[]::text[]),
    ('public','set_shop_business_mode','p_shop_id uuid, p_business_mode business_mode',ARRAY['authenticated','service_role']::text[]),
    ('shop_private','assert_purchase_entitlement','p_shop_id uuid',ARRAY[]::text[]),
    ('shop_private','assert_customer_read_access','p_shop_id uuid',ARRAY[]::text[]),
    ('public','invite_shop_staff','p_request_id uuid, p_shop_id uuid, p_email text, p_display_name text, p_job_title text, p_role_key text, p_location_ids uuid[]',ARRAY['authenticated','service_role']::text[]),
    ('shop_private','manage_shop_member','p_request_id uuid, p_shop_id uuid, p_membership_id uuid, p_action text, p_role_key text, p_location_ids uuid[], p_reason text',ARRAY['service_role']::text[]),
    ('shop_private','customer_access','p_shop_id uuid',ARRAY[]::text[]),
    ('shop_private','archive_customer','p_shop_id uuid, p_customer_id uuid',ARRAY[]::text[]),
    ('shop_private','list_customers','p_shop_id uuid, p_search text, p_is_active boolean, p_page integer, p_page_size integer',ARRAY[]::text[]),
    ('shop_private','get_customer','p_shop_id uuid, p_customer_id uuid',ARRAY[]::text[]),
    ('shop_private','save_customer','p_shop_id uuid, p_customer_id uuid, p_name text, p_phone text, p_email text, p_address text, p_notes text',ARRAY[]::text[]),
    ('public','customer_access','p_shop_id uuid',ARRAY['authenticated','service_role']::text[]),
    ('public','list_customers','p_shop_id uuid, p_search text, p_is_active boolean, p_page integer, p_page_size integer',ARRAY['authenticated','service_role']::text[]),
    ('public','get_customer','p_shop_id uuid, p_customer_id uuid',ARRAY['authenticated','service_role']::text[]),
